+            rv = htmlEditor->DeleteNode(brAtEndOfDiv, false, 1);
+            NS_ENSURE_SUCCESS(rv, rv);
+          }
         }

         // Use our own function instead of nsEditor::EndOfDocument() because
@@ -4765,7 +4768,6 @@ nsMsgCompose::SetIdentity(nsIMsgIdentity* aIdentity) {
